import {newProject,newLayer,migrate,validateProject,preset,History,copy,uid} from './model.js';
import {REFERENCE_PRESETS} from './legacy-engine.js';
import {estimate,csv} from './fabric.js';
import {Renderer} from './renderer.js';
import {ReferenceEditor,readImage} from './reference.js';
import {loadDraft,saveDraft} from './storage.js';
import {calibration} from './calibration.js';
const $=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=2)=>Number(n).toLocaleString('th-TH',{maximumFractionDigits:d,minimumFractionDigits:d});
let project=newProject(),selected=project.layers[0].id,history=new History(project),result,tab='design',saveTimer,toastTimer;
const layer=()=>project.layers.find(l=>l.id===selected)||project.layers[0];
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function download(name,data,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
let savedSeq=0;
function autosave(){clearTimeout(saveTimer);$('save-status').textContent='มีการแก้ไข…';saveTimer=setTimeout(async()=>{const seq=++savedSeq;try{await saveDraft(copy(project));if(seq===savedSeq)$('save-status').textContent='บันทึกในเครื่องแล้ว · '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});}catch{$('save-status').textContent='บันทึกอัตโนมัติไม่สำเร็จ — กรุณาบันทึก JSON';}},250);}
function commit(){try{validateProject(project);estimate(project);history.push(project);autosave();$('undo').disabled=history.index===0;$('redo').disabled=history.index===history.items.length-1;}catch(err){project=migrate(JSON.parse(history.items[history.index]));editor.set(project,layer());render();toast(err.message+' · คืนค่าก่อนแก้ไข');}}
function change(fn,{props=true}={}){const before=copy(project);try{fn();validateProject(project);estimate(project);render(props);commit();}catch(err){project=before;render(true);toast(err.message);}}
const renderer=new Renderer($('preview'),{onSelect:id=>{if(selected!==id){selected=id;editor.active=null;render(true);}},onMove:(dx,dy)=>{const l=layer();if(l.locked)return;l.x=Math.round((l.x+dx)*100)/100;l.y=Math.round((l.y+dy)*100)/100;render(false);},onCommit:()=>{commit();renderProperties();}});
const editor=new ReferenceEditor($('reference-canvas'),{change:()=>{renderer.set(project,selected);renderSummary();},commit:()=>{commit();renderProperties();},select:()=>renderProperties()});
function field(key,label,value,{min=0,max=10000,step=1,type='number',options,wide=false,attr='layer'}={}){
 const control=options?`<select data-${attr}="${key}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${safe(t)}</option>`).join('')}</select>`:`<input data-${attr}="${key}" type="${type}" value="${safe(value)}" ${type==='number'?`min="${min}" max="${max}" step="${step}"`:''}>`;
 return `<label class="field ${wide?'wide':''}">${label}${control}</label>`;
}
const shapes=[['straight','ตรง · Straight'],['swag','หย่อน · Swag'],['scallop','หยักโค้ง · Scallop'],['arch','โค้งกลาง · Arch'],['cross','พาดเฉียง · Cross Drape'],['side','ปัดข้าง · Side Sweep'],['center','รวบกลาง · Center Tie'],['trace','ถอดแบบ · Trace'],['legacy','รูปทรง V5 เดิม']];
function renderProperties(){const l=layer();$('active-label').textContent=`LAYER ${String(project.layers.indexOf(l)+1).padStart(2,'0')}`;let h=`${l.locked?'<div class="locked-note">ล็อกการแก้ไขชั้นนี้อยู่ · ปลดล็อกในรายการชั้นผ้า</div>':''}<fieldset style="border:0;padding:0;margin:0;min-width:0" ${l.locked?'disabled':''}><section class="field-section"><h3>01 / รูปแบบและขนาด</h3><div class="fields">`;
 h+=field('name','ชื่อชั้นผ้า',l.name,{type:'text',wide:true});h+=field('mode','ลักษณะติดตั้ง',l.mode,{wide:true,options:[['backdrop','ฉากตั้ง'],['ceilingDrape','ผ้าเพดาน / ช่วงแขวน']]});h+=field('shape','รูปทรง',l.shape,{options:shapes,wide:true});
 for(const [k,t,max] of [['widthCm','กว้าง (ซม.)',5000],['heightCm','สูง (ซม.)',5000],['depth','นูนลึก (ซม.)',500],['sagCm','หย่อน / โค้ง (ซม.)',1500]])h+=field(k,t,l[k],{min:k.includes('Cm')&&k!=='sagCm'?1:0,max});
 if(['side','legacy'].includes(l.shape))h+=field('sweepCm','ระยะปัดข้าง (ซม.)',l.sweepCm,{min:-150,max:150});
 if(l.shape==='cross')h+=field('direction','ทิศทางพาด',String(l.direction),{options:[['1','ลงทางขวา'],['-1','ลงทางซ้าย']]});
 if(l.shape==='scallop')h+=field('repeats','จำนวนหยัก',l.repeats,{min:1,max:8});
 if(l.shape==='legacy'){h+=field('curveType','โค้ง V5',l.curveType,{options:['straight','arch','scallop','wave','diagonal'].map(v=>[v,v])});h+=field('curveDepthCm','ระยะโค้ง V5',l.curveDepthCm,{max:300});}
 if(l.mode==='ceilingDrape'){h+=field('spanCm','ระยะต่อช่วง (ซม.)',l.spanCm,{min:1,max:5000})+field('swags','จำนวนช่วง',l.swags,{min:1,max:24})+field('method','วิธีคิดผ้าเพดาน',l.method,{wide:true,options:[['exact','Catenary ปลายระดับเท่ากัน'],['brief','สูตรประมาณ V5']]});}
 h+='</div></section><section class="field-section"><h3>02 / ตำแหน่งและผิวผ้า</h3><div class="fields">';
 for(const k of ['x','y','z'])h+=field(k,({x:'X ซ้าย–ขวา',y:'Y ลงจากบน',z:'Z ออกด้านหน้า'})[k]+' (ซม.)',l[k],{min:-10000,max:10000,step:1});
 h+=field('band','กลุ่มชั้น',l.band,{options:[['back','หลัง'],['middle','กลาง'],['front','หน้า']]})+field('color','สีผ้า',l.color,{type:'color'})+field('opacity','ความทึบ (%)',l.opacity,{max:100})+field('roughness','ความด้าน (0–1)',l.roughness,{max:1,step:.05})+field('transmission','ความโปร่ง (0–1)',l.transmission,{max:1,step:.05});
 h+='</div></section><section class="field-section"><h3>03 / วัสดุและแผนตัด</h3><div class="fields">';
 for(const [k,t,min,max,step] of [['fullness','Fullness Ratio',1,6,.1],['fabricWidth','หน้าผ้า (ซม.)',1,1000,1],['quantity','จำนวนชุด',1,9999,1],['unitPrice','บาท / เมตร',0,100000,1]])h+=field(k,t,l[k],{min,max,step});
 h+=field('estimateMode','วิธีประมาณวัสดุ',l.estimateMode,{wide:true,options:[['panels','V6 · แผนตัดต่อ Panel'],...(l.legacyLayer?[['legacy','V5 · คงสูตรเดิม']]:[])]});h+='</div>';
 if(l.estimateMode==='legacy')h+='<p class="muted">เก็บสูตรและส่วนเผื่อ V5 เดิมไว้ เปลี่ยนเป็น V6 เพื่อแจกแจงการตัดตามรูปทรงที่แก้ไข</p>';
 else{h+='<div class="fields" style="margin-top:12px">';for(const [k,t,max] of [['seamCm','เผื่อหัว/ท้าย ต่อด้าน (ซม.)',200],['sideSeamCm','ตะเข็บข้าง ต่อด้าน (ซม.)',200],['shrinkage','การหดตัว (%)',30],['patternRepeatCm','ระยะซ้ำของลาย (ซม.)',200],['wastage','เผื่อเสีย (%)',100]])h+=field(k,t,l.allowance[k],{max,step:.5,attr:'allowance'});h+='</div>';}
 h+='</section>';
 if(l.shape==='trace'){
  h+='<section class="field-section"><h3>04 / เส้นโค้งและจุดอ้างอิง</h3><div class="fields">'+field('curve','รูปแบบเส้น',l.curve,{wide:true,options:[['bezier','Bézier · ลาก Handle'],['catenary','Catenary · สายหย่อน']]})+'</div><p class="muted">จุดและ Handle แก้บนภาพที่ปรับมุมแล้วได้ บทบาทจุดเป็นหมายเหตุประกอบการติดตั้ง ไม่ใช่ตัวแก้สมการแรงผ้า</p>';
  const a=editor.active&&l.anchors[editor.active.edge]?.[editor.active.index];if(a){h+=`<b class="muted">จุด ${editor.active.index+1} / ${editor.active.edge==='top'?'บน':'ล่าง'}</b><div class="anchor-table">`+field('x','X (สัดส่วน)',a.x,{attr:'anchor',min:-5,max:5,step:.01})+field('y','Y (สัดส่วน)',a.y,{attr:'anchor',min:-5,max:5,step:.01})+field('role','บทบาทจุด',a.role,{attr:'anchor',wide:true,options:[['hang','จุดแขวน'],['tie','จุดผูก'],['gather','จุดรวบ'],['release','จุดปล่อย']]})+'</div><button id="add-handles" style="margin-top:10px">เพิ่ม / รีเซ็ต Handle</button>';}
  h+='</section>';
 }
 h+='</fieldset>';$('properties').innerHTML=h;
 $('add-handles')?.addEventListener('click',()=>change(()=>{const a=l.anchors[editor.active.edge][editor.active.index];a.in={x:a.x-.12,y:a.y};a.out={x:a.x+.12,y:a.y};}));
}
function renderLayers(){$('layer-count').textContent=project.layers.length+' LAYERS';$('layer-list').innerHTML=project.layers.map((l,i)=>`<article class="layer-row ${l.id===selected?'selected':''} ${!l.visible?'muted-layer':''}" tabindex="0" data-select="${safe(l.id)}" aria-label="เลือก ${safe(l.name)}"><div class="layer-main"><span class="color-chip" style="background:${/^#[\da-f]{6}$/i.test(l.color)?l.color:'#ddd'}"></span><div><b>${safe(l.name)}</b><small>${l.widthCm} × ${l.heightCm} ซม. · ${{back:'หลัง',middle:'กลาง',front:'หน้า'}[l.band]} · Z ${l.z}</small></div></div><div class="row-actions"><button data-action="visible" data-id="${l.id}" title="ซ่อนภาพเท่านั้น ยังนับใน BOM">${l.visible?'◉':'○'}</button><button data-action="locked" data-id="${l.id}" title="ล็อก / ปลดล็อก">${l.locked?'ล็อก':'แก้ได้'}</button><button data-action="up" data-id="${l.id}" title="ไปด้านหลัง" ${i===0?'disabled':''}>↑</button><button data-action="down" data-id="${l.id}" title="ไปด้านหน้า" ${i===project.layers.length-1?'disabled':''}>↓</button><button data-action="delete" data-id="${l.id}" title="ลบชั้น" ${project.layers.length===1||l.locked?'disabled':''}>×</button></div></article>`).join('');}
function renderSummary(){try{result=estimate(project);$('sum-theory').textContent=num(result.theory);$('sum-purchase').textContent=num(result.purchase);$('sum-bars').textContent=result.steel.totalBars+(result.steel.complete?'':' *');$('sum-cost').textContent='฿ '+num(result.total,0);renderBOM();renderSteelResults();}catch(err){result=null;for(const id of ['sum-theory','sum-purchase','sum-bars','sum-cost'])$(id).textContent='—';$('bom-panel').innerHTML=`<p class="notice error">${safe(err.message)}</p>`;}}
function renderBOM(){if(!result)return;$('bom-panel').innerHTML=`<div class="data-heading"><h2>ปริมาณผ้าและต้นทุน</h2><button id="export-bom">BOM / CSV ↓</button></div><div class="table-scroll"><table><thead><tr><th>ชั้นผ้า</th><th>Panel / ช่วง</th><th>ทฤษฎี ม.</th><th>ส่วนเผื่อ ม.</th><th>ปัดเพิ่ม ม.</th><th>สั่งซื้อ ม.</th><th>บาท/ม.</th><th>รวม บาท</th></tr></thead><tbody>${result.fabric.map(r=>`<tr><td>${safe(r.name)}</td><td class="num">${r.panelCount||r.swagCount}</td>${[r.theoreticalMeters,r.allowanceMeters,r.roundingMeters,r.purchaseMeters,r.unitPrice,r.fabricCost].map(n=>`<td class="num">${num(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${result.fabric.map(r=>`<details><summary>${safe(r.name)} · ดูวิธีคิดและความยาวตัด</summary><p class="muted">${safe(r.note)}</p>${r.cuts.length?`<div class="table-scroll"><table><thead><tr><th>ผืน</th><th>จำนวน</th><th>รูปทรง ซม.</th><th>ตะเข็บ ซม.</th><th>หดตัว ซม.</th><th>จับลาย ซม.</th><th>ตัดจริง ซม.</th></tr></thead><tbody>${r.cuts.map(c=>`<tr>${[c.panel,c.quantity,...[c.rawCm,c.seamCm,c.shrinkageCm,c.patternCm,c.cutCm].map(n=>num(n))].map(n=>`<td>${n}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</details>`).join('')}<p class="notice">การซ่อนชั้นผ้ามีผลกับภาพเท่านั้น ยังนับวัสดุใน BOM · แผนตัดไม่รวมการจัดเศษผ้าระหว่าง Layer · ไม่รวม VAT / ค่าขนส่ง เว้นแต่กรอกในค่าใช้จ่ายอื่น</p>`;$('export-bom').onclick=exportBOM;}
function renderSteelEditor(){const s=project.steel;$('steel-panel').innerHTML=`<div class="data-heading"><h2>เหล็ก 6,000 มม. / รายการตัด</h2><button id="add-steel">＋ รายการเหล็ก</button></div><p class="muted">หน้าตัดและความยาวหน่วย มม. · ราคาเป็นบาทต่อเส้น 6 ม. · จัดกลุ่มตามชนิด หน้าตัด ความหนา และเกรด</p><div class="table-scroll"><div class="steel-row steel-labels">${['ชื่อ/หน้าที่','ชนิด','กว้าง/Ø','สูง','หนา','ยาว','จำนวน','บาท/เส้น',''].map(t=>`<span>${t}</span>`).join('')}</div>${s.items.map((item,i)=>`<div class="steel-row" data-steel-row="${i}"><input data-steel="name" aria-label="ชื่อเหล็ก ${i+1}" value="${safe(item.name)}"><select data-steel="type" aria-label="ชนิดเหล็ก ${i+1}">${['SHS','RHS','ROUND','SOLID'].map(t=>`<option ${item.type===t?'selected':''}>${t}</option>`).join('')}</select>${['w','h','t','length','quantity','price'].map(k=>`<input type="number" data-steel="${k}" aria-label="${k} เหล็ก ${i+1}" value="${item[k]}" min="${k==='price'||k==='t'?0:1}" step="${k==='t'?'.1':1}" ${item.type==='ROUND'&&['h','t'].includes(k)||item.type==='SOLID'&&k==='t'?'disabled':''}>`).join('')}<button data-delete-steel="${i}" aria-label="ลบเหล็ก ${i+1}">×</button></div><label class="muted">เกรด / วัสดุ <input data-grade="${i}" value="${safe(item.grade)}" style="padding:4px;margin-bottom:8px;font-size:10px"></label>`).join('')}</div><label class="field">Kerf ต่อชิ้น (มม.)<input id="kerf" type="number" min="0" max="100" step=".1" value="${s.kerf}" style="width:100px;margin:10px"></label><div id="steel-results"></div><div class="data-heading"><h2>เพลทฐานและอุปกรณ์</h2><button id="add-accessory">＋ อุปกรณ์</button></div><p class="muted">ชื่อรายการ · จำนวนชิ้น · บาทต่อชิ้น</p>${s.accessories.map((a,i)=>`<div class="accessory-row" data-accessory-row="${i}"><input data-accessory="name" aria-label="ชื่ออุปกรณ์ ${i+1}" value="${safe(a.name)}"><input data-accessory="quantity" aria-label="จำนวนอุปกรณ์ ${i+1}" type="number" min="0" value="${a.quantity}"><input data-accessory="price" aria-label="ราคาอุปกรณ์ ${i+1}" type="number" min="0" value="${a.price}"><button data-delete-accessory="${i}">×</button></div>`).join('')}<p class="notice warning">น้ำหนักเป็นค่าเบื้องต้นจากหน้าตัดอุดมคติ (ความหนาแน่น 7,850 กก./ม³) ไม่รวมเพลท/รอยเชื่อม ไม่ใช่การยืนยันความปลอดภัย ต้องให้วิศวกรตรวจแรงลม จุดต่อ ฐานราก ค้ำยัน และเสถียรภาพก่อนติดตั้งจริง</p>`;
 $('add-steel').onclick=()=>change(()=>{s.items.push({id:uid(),name:'เหล็กใหม่',type:'SHS',w:40,h:40,t:2,grade:'unspecified',length:2500,quantity:1,price:320});});
 $('add-accessory').onclick=()=>change(()=>s.accessories.push({id:uid(),name:'อุปกรณ์ใหม่',quantity:1,price:0}));
 $('kerf').onchange=e=>change(()=>s.kerf=Number(e.target.value));renderSteelResults();}
function renderSteelResults(){if(!result||!$('steel-results'))return;const s=result.steel;$('steel-results').innerHTML=`${s.errors.map(t=>`<p class="notice error">${safe(t)} — ยังไม่รวมชิ้นนี้ในยอดสั่งซื้อ</p>`).join('')}<div class="data-heading"><p class="muted">${s.totalBars} เส้น · ฿ ${num(s.cost)} · น้ำหนักเหล็กใช้งาน ${num(s.weight)} กก. · ผ้า ${num(result.fabricKg)} กก.</p><button id="export-cut">Cut List / CSV ↓</button></div>${s.groups.map(g=>`<details open><summary>${safe(g.spec.type)} ${g.spec.w}×${g.spec.h}×${g.spec.t} / ${safe(g.spec.grade)} · ${g.stockCount} เส้น · เศษ+Kerf ${num(g.wastePercent,1)}% · ${g.optimalProven?'จำนวนเส้นเท่าขอบเขตต่ำสุด':'แผน Best-fit decreasing'}</summary>${g.warnings.map(t=>`<p class="notice warning">${safe(t)}</p>`).join('')}${g.bars.map((b,i)=>`<div class="muted">เส้น ${i+1}: ${b.cuts.map(c=>`${safe(c.name)} ${c.length}`).join(' + ')} มม. · เศษ ${num(b.remaining,1)} มม. · Kerf ${num(b.cuts.reduce((s,c)=>s+c.kerf,0),1)} มม.</div><div class="cutbar">${b.cuts.map(c=>`<span style="width:${c.length/60}%" title="${safe(c.name)} ${c.length} มม.">${c.length}</span>`).join('')}</div>`).join('')}</details>`).join('')}<p class="notice">Best-fit decreasing ให้แผนที่ตัดได้ แต่ไม่รับรองจำนวนเส้นต่ำสุดทุกกรณี · คิด Kerf หนึ่งครั้งต่อชิ้น ยกเว้นเส้นเต็มที่ไม่ตัด · เศษแสดงแยกจาก Kerf · ไม่ต่อชิ้นเกิน 6 เมตรโดยอัตโนมัติ</p>`;$('export-cut').onclick=exportCut;}
function renderSettings(){$('settings-panel').innerHTML=`<div class="data-heading"><h2>ขนาดพื้นที่และต้นทุนเพิ่มเติม</h2></div><div class="fields">${[['width','กว้างฉาก (ซม.)',1,5000],['height','สูงฉาก (ซม.)',1,5000],['increment','ปัดยอดผ้า (เมตร)',.01,100],['laborCost','ค่าแรง/ติดตั้ง (บาท)',0,100000],['otherCost','ค่าใช้จ่ายอื่น (บาท)',0,100000],['gsm','น้ำหนักผ้าเฉลี่ย (GSM)',1,2000]].map(([k,t,min,max])=>field(k,t,project[k],{attr:'project',min,max,step:k==='increment'?.1:1})).join('')}${field('quality','คุณภาพพรีวิว',project.render.quality,{attr:'render',options:[['auto','อัตโนมัติตามหน้าจอ'],['low','ประหยัด'],['high','ละเอียด']]})}</div><p class="notice">ขนาดพื้นที่ปรับกรอบพรีวิว ไม่ย่อ/ขยาย Layer อัตโนมัติ · ระดับความโปร่งและความด้านเป็นแบบจำลองการแสดงผล ไม่ใช่คุณสมบัติวัดจากผ้าจริง</p>`;}
function render(props=true){if(!project.layers.some(l=>l.id===selected))selected=project.layers[0].id;renderer.set(project,selected);editor.set(project,layer());renderLayers();if(props){renderProperties();renderSteelEditor();renderSettings();}$('project-name').value=project.name;$('ref-width').value=project.reference.width;$('ref-height').value=project.reference.height;$('render-look').value=project.render.look;$('person-toggle').checked=project.render.person;$('person-height').value=project.render.personHeight;$('frame-toggle').checked=project.render.frame;$('floral-toggle').checked=project.render.floral;renderSummary();}
async function replaceProject(p){const next=migrate(p);estimate(next);if(next.reference.calibrated)calibration(next.reference.quad,next.reference.width,next.reference.height);await editor.setImage(next.reference.image);project=next;selected=project.layers[0].id;editor.active=null;editor.set(project,layer());if(project.reference.calibrated)editor.rectify();render(true);commit();}
function setTab(next){tab=next;if(next==='compare')renderer.view('front');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===next));$('reference-tools').hidden=next==='design';$('reference-stage').hidden=next==='design';$('design-stage').hidden=next==='reference';$('stage-layout').classList.toggle('compare',next==='compare');editor.draw();renderer.draw();}
function exportBOM(){if(!result)return;const rows=[['ประเภท','ชื่อ','Panel/ช่วง','ทฤษฎี ม.','ส่วนเผื่อ ม.','ปัดเพิ่ม ม.','สั่งซื้อ ม.','บาท/ม.','ต้นทุน บาท','วิธีคิด']];for(const r of result.fabric)rows.push(['FABRIC',r.name,r.panelCount||r.swagCount,r.theoreticalMeters,r.allowanceMeters,r.roundingMeters,r.purchaseMeters,r.unitPrice,r.fabricCost,r.note]);for(const r of result.fabric)for(const c of r.cuts)rows.push(['FABRIC_CUT',r.name,`Panel ${c.panel}`,`จำนวน ${c.quantity}`,`ทฤษฎี ${c.rawCm} ซม.`,`ตะเข็บ ${c.seamCm} ซม.`,`หดตัว ${c.shrinkageCm} ซม.`,`จับลาย ${c.patternCm} ซม.`,`ตัด ${c.cutCm} ซม.`]);for(const g of result.steel.groups)rows.push(['STEEL',`${g.key} · ${g.stockCount} เส้น`,,,,,,,g.cost]);for(const a of project.steel.accessories)rows.push(['ACCESSORY',a.name,a.quantity,,,,,a.price,a.price*a.quantity]);rows.push(['LABOR','','','','','','','',project.laborCost],['OTHER','','','','','','','',project.otherCost],['TOTAL',result.steel.complete?'ประมาณการ':'รายการเหล็กไม่ครบ — ตรวจคำเตือน','','','','','','',result.total]);download('Wedding_Fabric_V6_BOM.csv',csv(rows),'text/csv;charset=utf-8');}
function exportCut(){if(!result)return;const rows=[['ชนิด/หน้าตัด/เกรด','เส้นที่','รายการ','ยาว มม.','Kerf มม.','เศษเส้น มม.','บาท/เส้น','หมายเหตุ']];for(const g of result.steel.groups)g.bars.forEach((b,i)=>b.cuts.forEach((c,j)=>rows.push([g.key,i+1,c.name,c.length,c.kerf,j===0?b.remaining:'',j===0?g.price:'',j===0?'Best-fit decreasing':'' ])));for(const e of result.steel.errors)rows.push(['ERROR','','','','','','',e]);download('Wedding_Fabric_V6_Cut_List.csv',csv(rows),'text/csv;charset=utf-8');}
// Properties are committed on change: one undo step per typed field or slider gesture.
$('properties').addEventListener('change',e=>{const el=e.target,l=layer();if(l.locked)return;const k=el.dataset.layer,a=el.dataset.allowance,anchor=el.dataset.anchor;change(()=>{if(k){l[k]=['name','shape','mode','band','color','curve','estimateMode','method','curveType'].includes(k)?el.value:Number(el.value);if(k==='shape'&&l.shape!=='legacy')l.estimateMode='panels';if(k==='shape'&&l.shape==='trace')setTab('reference');if(k==='band')l.z={back:0,middle:15,front:30}[l.band];}if(a)l.allowance[a]=Number(el.value);if(anchor&&editor.active)l.anchors[editor.active.edge][editor.active.index][anchor]=anchor==='role'?el.value:Number(el.value);});});
$('settings-panel').addEventListener('change',e=>{const el=e.target;change(()=>{if(el.dataset.project)project[el.dataset.project]=Number(el.value);if(el.dataset.render)project.render[el.dataset.render]=el.value;});});
$('steel-panel').addEventListener('change',e=>{const el=e.target;change(()=>{if(el.dataset.steel){const i=Number(el.closest('[data-steel-row]').dataset.steelRow),k=el.dataset.steel;project.steel.items[i][k]=['name','type'].includes(k)?el.value:Number(el.value);if(project.steel.items[i].type==='SHS'){if(k==='h')project.steel.items[i].w=project.steel.items[i].h;else project.steel.items[i].h=project.steel.items[i].w;}}if(el.dataset.grade!==undefined)project.steel.items[Number(el.dataset.grade)].grade=el.value;if(el.dataset.accessory){const i=Number(el.closest('[data-accessory-row]').dataset.accessoryRow),k=el.dataset.accessory;project.steel.accessories[i][k]=k==='name'?el.value:Number(el.value);}});});
$('steel-panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.deleteSteel!==undefined)change(()=>project.steel.items.splice(Number(b.dataset.deleteSteel),1));if(b.dataset.deleteAccessory!==undefined)change(()=>project.steel.accessories.splice(Number(b.dataset.deleteAccessory),1));});
$('layer-list').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const l=project.layers.find(l=>l.id===b.dataset.id),i=project.layers.indexOf(l),a=b.dataset.action;change(()=>{if(a==='visible'||a==='locked')l[a]=!l[a];if(a==='delete'&&!l.locked&&project.layers.length>1)project.layers.splice(i,1);if(a==='up'||a==='down'){const j=i+(a==='up'?-1:1);if(j<0||j>=project.layers.length)return;const other=project.layers[j];if(l.locked||other.locked){toast('ปลดล็อกชั้นก่อนเปลี่ยนลำดับ');return;}[l.z,other.z]=[other.z,l.z];[project.layers[i],project.layers[j]]=[other,l];}});return;}const row=e.target.closest('[data-select]');if(row){selected=row.dataset.select;editor.active=null;render();}});
$('layer-list').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.select){selected=e.target.dataset.select;render();}});
$('add-layer').onclick=()=>change(()=>{if(project.layers.length>=80)throw new Error('สูงสุด 80 ชั้น');const l=newLayer();project.layers.push(l);selected=l.id;editor.active=null;});
$('duplicate-layer').onclick=()=>change(()=>{if(project.layers.length>=80)throw new Error('สูงสุด 80 ชั้น');const l=copy(layer());l.id=uid();l.name+=' สำเนา';l.z+=8;l.locked=false;project.layers.push(l);selected=l.id;});
$('project-name').onchange=e=>change(()=>project.name=e.target.value.slice(0,120),{props:false});
$('new-project').onclick=async()=>{if(confirm('เริ่มโปรเจกต์ใหม่? ย้อนกลับได้ด้วย Undo แต่ควรบันทึก JSON ของงานเดิม'))await replaceProject(newProject());};
$('save-project').onclick=()=>download('Wedding_Fabric_Studio_V6_Project.json',JSON.stringify({...project,exportedAt:new Date().toISOString()},null,2));
$('import-project').onclick=()=>$('project-file').click();$('project-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw new Error('โปรเจกต์ต้องไม่เกิน 25 MB');await replaceProject(JSON.parse(await f.text()));toast('เปิดโปรเจกต์แล้ว');}catch(err){toast(err.message);}e.target.value='';};
async function travel(direction){const next=direction==='undo'?history.undo():history.redo();project=migrate(next);selected=project.layers.find(l=>l.id===selected)?.id||project.layers[0].id;editor.active=null;await editor.setImage(project.reference.image);editor.set(project,layer());if(project.reference.calibrated)editor.rectify();render();autosave();$('undo').disabled=history.index===0;$('redo').disabled=history.index===history.items.length-1;}
$('undo').onclick=()=>travel('undo');$('redo').onclick=()=>travel('redo');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();travel(e.shiftKey?'redo':'undo');}});
$('preview').addEventListener('keydown',e=>{const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(!dirs[e.key]||layer().locked)return;e.preventDefault();change(()=>{const [x,y]=dirs[e.key],d=e.shiftKey?10:1;layer().x+=x*d;layer().y+=y*d;});});
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>setTab(b.dataset.tab);
for(const b of document.querySelectorAll('[data-camera]'))b.onclick=()=>{renderer.view(b.dataset.camera);document.querySelectorAll('[data-camera]').forEach(n=>n.classList.toggle('active',n===b));};
for(const b of document.querySelectorAll('[data-tool]'))b.onclick=()=>{renderer.tool=b.dataset.tool;if(renderer.tool==='move')renderer.view('front');document.querySelectorAll('[data-tool]').forEach(n=>n.classList.toggle('active',n===b));$('stage-hint').textContent=renderer.tool==='move'?'ลากชั้นผ้าในมุมหน้า · ปุ่มลูกศร = 1 ซม. · Shift = 10 ซม.':'ลากเพื่อหมุน · Scroll เพื่อซูม · Shift + ลากเพื่อเลื่อน';};
$('zoom-in').onclick=()=>{renderer.zoom=Math.min(4,renderer.zoom*1.2);renderer.draw();};$('zoom-out').onclick=()=>{renderer.zoom=Math.max(.25,renderer.zoom/1.2);renderer.draw();};
$('camera-reset').onclick=()=>renderer.view('perspective');
$('render-look').onchange=e=>change(()=>project.render.look=e.target.value,{props:false});
for(const [id,key] of [['person-toggle','person'],['frame-toggle','frame'],['floral-toggle','floral']])$(id).onchange=e=>change(()=>project.render[key]=e.target.checked,{props:false});
$('person-height').onchange=e=>change(()=>{const h=Number(e.target.value);if(h<80||h>220)throw new Error('ความสูงคน 80–220 ซม.');project.render.personHeight=h;},{props:false});
$('export-png').onclick=()=>{const target=tab==='reference'?$('reference-canvas'):$('preview');target.toBlob(blob=>blob&&download('Wedding_Fabric_V6_Preview.png',blob),'image/png');};
for(const b of document.querySelectorAll('[data-panel]'))b.onclick=()=>{for(const p of ['bom','steel','settings'])$(p+'-panel').hidden=p!==b.dataset.panel;document.querySelectorAll('[data-panel]').forEach(n=>n.classList.toggle('active',n===b));};
$('preset').innerHTML+=Object.entries(REFERENCE_PRESETS).map(([k,v])=>`<option value="${k}">${safe(v.label)}</option>`).join('');$('preset').onchange=async e=>{if(e.target.value)await replaceProject(preset(e.target.value));e.target.value='';};
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();
async function upload(file){try{const image=await readImage(file);project.reference={...project.reference,image,quad:[],calibrated:false};editor.set(project,layer());await editor.setImage(image);editor.mode='calibrate';editor.original=true;$('show-original').checked=true;setTab('reference');$('reference-status').textContent='เลือก 4 มุม: ซ้ายบน → ขวาบน → ขวาล่าง → ซ้ายล่าง';commit();}catch(err){toast(err.message);}}
$('reference-file').onchange=e=>{if(e.target.files[0])upload(e.target.files[0]);e.target.value='';};$('reference-stage').ondragover=e=>e.preventDefault();$('reference-stage').ondrop=e=>{e.preventDefault();upload(e.dataTransfer.files[0]);};
$('calibrate-start').onclick=()=>{if(!editor.image){toast('อัปโหลดภาพก่อน');return;}project.reference.quad=[];project.reference.calibrated=false;editor.mode='calibrate';editor.original=true;$('show-original').checked=true;editor.draw();$('reference-status').textContent='เลือกมุม 1 ซ้ายบน → 2 ขวาบน → 3 ขวาล่าง → 4 ซ้ายล่าง · ลากจุดเพื่อปรับ';commit();};
for(const id of ['ref-width','ref-height'])$(id).onchange=e=>change(()=>{project.reference[id==='ref-width'?'width':'height']=Number(e.target.value);project.reference.calibrated=false;editor.rectified=null;editor.original=true;});
$('calibrate-apply').onclick=()=>{try{const r=project.reference;calibration(r.quad,r.width,r.height);editor.rectify();r.calibrated=true;project.width=r.width;project.height=r.height;$('show-original').checked=false;$('reference-caption').textContent='ปรับ Perspective แล้ว · ระนาบ 2D';$('reference-status').textContent='ปรับระนาบแล้ว · สร้างชั้น Trace แล้วลากขอบบน/ล่าง · ความลึกยังต้องระบุเอง';commit();render();}catch(err){toast(err.message);}};
$('show-original').onchange=e=>{editor.original=e.target.checked;editor.draw();};$('show-overlay').onchange=e=>{editor.overlay=e.target.checked;editor.draw();};$('trace-edge').onchange=e=>editor.edge=e.target.value;
$('trace-new').onclick=()=>{if(!project.reference.calibrated){toast('ปรับ Perspective และยืนยันขนาดก่อนสร้างชั้น Trace');return;}change(()=>{const r=project.reference,l=newLayer({name:'ผ้าถอดแบบ '+(project.layers.length+1),shape:'trace',widthCm:r.width,heightCm:r.height,x:0,y:0,z:25,source:{kind:'manual-trace',referenceSize:[r.width,r.height],confirmedDepth:false},anchors:{top:[{x:.05,y:.08,role:'hang',out:{x:.35,y:.3}},{x:.95,y:.08,role:'hang',in:{x:.65,y:.3}}],bottom:[{x:.05,y:.55,role:'release',out:{x:.35,y:.8}},{x:.95,y:.55,role:'release',in:{x:.65,y:.8}}]}});project.layers.push(l);selected=l.id;editor.active={edge:'top',index:0};editor.mode='edit';editor.original=false;$('show-original').checked=false;});};
$('anchor-add').onclick=()=>{if(layer().shape!=='trace'||layer().locked){toast('เลือกชั้น Trace ที่ปลดล็อกก่อน');return;}editor.mode='add';$('reference-status').textContent='คลิกตำแหน่งเพื่อเพิ่ม Anchor บนเส้น '+(editor.edge==='top'?'ขอบบน':'ขอบล่าง');};
$('anchor-remove').onclick=()=>{if(!editor.active||layer().locked)return;change(()=>{const pts=layer().anchors[editor.active.edge];if(pts.length<=2)throw new Error('แต่ละเส้นต้องเหลืออย่างน้อย 2 จุด');pts.splice(editor.active.index,1);editor.active=null;});};
$('example').onclick=async()=>{try{const response=await fetch('./examples/traced-project.json');if(!response.ok)throw new Error('ไม่พบไฟล์ตัวอย่าง');await replaceProject(await response.json());setTab('compare');toast('ตัวอย่างภาพสังเคราะห์ที่ทราบตำแหน่งจริง — ใช้เรียนรู้การปรับมุมและ Trace');}catch(err){toast(err.message);}};
async function boot(){try{const stored=await loadDraft();if(stored){project=migrate(stored);}else{for(const key of ['wfs-v5-project','wfs-v4-project','wfs-v3-project']){const s=localStorage.getItem(key);if(s){project=migrate(JSON.parse(s));toast('นำเข้าแบบร่าง V5 เดิมแล้ว โดยคงสูตรเดิม');break;}}}}catch(err){toast('เปิดแบบร่างไม่สำเร็จ: '+err.message);}selected=project.layers[0].id;history=new History(project);editor.set(project,layer());try{await editor.setImage(project.reference.image);if(project.reference.calibrated)editor.rectify();}catch(err){toast(err.message);}render();commit();}
boot();
